// Process-scoped multi-file SOPs; files remain in this browser's IndexedDB in the prototype.
const SOPKEY='power-mes-process-sops-v1';let sopGroups=[],sopSelection='',sopUploadFiles=[],sopUploading=false;let sopPlayers=new Map(),sopPlayerSeq=0;const sopPlayback=new Map();
try{let saved=JSON.parse(localStorage.getItem(SOPKEY)||'[]');if(Array.isArray(saved))sopGroups=saved}catch{}
function sopDB(){return new Promise((resolve,reject)=>{let r=indexedDB.open('power-mes-sop-files',1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains('files'))r.result.createObjectStore('files')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('无法打开文件存储，请检查浏览器存储权限'))})}
async function sopStoreFiles(entries){let db=await sopDB();try{await new Promise((resolve,reject)=>{let tx=db.transaction('files','readwrite');for(let e of entries)tx.objectStore('files').put(e.file,e.id);tx.oncomplete=resolve;tx.onabort=tx.onerror=()=>reject(Error('文件保存失败，可能超过浏览器存储额度'))})}finally{db.close()}}
async function sopReadFile(id){let db=await sopDB();try{return await new Promise((resolve,reject)=>{let tx=db.transaction('files','readonly'),r=tx.objectStore('files').get(id);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(Error('文件读取失败'))})}finally{db.close()}}
async function sopRemoveFiles(ids){let db=await sopDB();try{await new Promise((resolve,reject)=>{let tx=db.transaction('files','readwrite');ids.forEach(id=>tx.objectStore('files').delete(id));tx.oncomplete=resolve;tx.onerror=()=>reject(Error('文件清理失败'))})}finally{db.close()}}
function saveSops(){localStorage.setItem(SOPKEY,JSON.stringify(sopGroups))}function sopCanEdit(){return auth&&['admin','quality'].includes(auth.role)}function sopRequireEdit(){if(!sopCanEdit()){toast('当前角色无 SOP 发布权限');return false}return true}
function sopType(file){if(['image/png','image/jpeg','image/webp','image/gif'].includes(file.type))return 'image';if(file.type==='application/pdf')return 'pdf';if(['video/mp4','video/webm'].includes(file.type))return 'video';throw Error(file.name+'：仅支持 PNG、JPEG、WebP、GIF、PDF、MP4、WebM')}
function sopSaveSelection(){if(!sopSelection&&sopGroups.length)sopSelection=sopGroups[0].id;return sopGroups.find(g=>g.id===sopSelection)}
renderers.sop=function(){let g=sopSaveSelection();return heading('SOP 作业指导书','按工序管理多份文件，后台预览，工位顺序自动播放',sopCanEdit()?button('＋ 上传 SOP 文件组',"uploadSop()",'primary'):'')+`<div class="notice">SOP 只关联工序，不关联产品。每组文件按下方顺序播放，图片与 PDF 按设定时间切换，视频播放结束后切换下一份。</div><div class="gridhalf">${panel('工序指导书库',sopGroups.length?sopGroups.map(x=>`<div class="lineitem"><div class="lineicon">▧</div><div class="fill"><b>${escapeHtml(x.title)}</b><p class="sub">${steps[x.process]} · ${escapeHtml(x.version)} · ${x.files.length} 份文件</p></div>${badge(x.status)}${button('预览',`selectSopGroup('${x.id}')`)}</div>`).join(''):'<div class="sop-empty"><h3>还没有上传指导书</h3><p>选择工序，一次添加多份图片、PDF 或视频。</p></div>')}${g?panel(escapeHtml(g.title),`<div class="actions" style="margin-bottom:15px">${badge(steps[g.process])}${badge(g.version)}${badge(g.status)}${sopCanEdit()&&g.status!=='已发布'?button('审核并发布',`publishSopGroup('${g.id}')`,'primary'):''}</div>${sopPlayerMarkup(g)}<h3 style="margin:20px 0 10px">播放文件顺序</h3>${g.files.map((f,i)=>`<div class="sop-file-row"><span class="badge">${i+1}</span><span class="fill">${escapeHtml(f.name)}<small>${f.type.toUpperCase()} · ${(f.size/1024/1024).toFixed(2)} MB</small></span>${button('预览',`sopPreviewFile('${g.id}',${i})`)}</div>`).join('')}<p class="hint">原型文件保存在本浏览器。跨设备接收 SOP 需要接入后台文件服务。</p>`):panel('文件预览','<div class="sop-empty">上传并选择指导书后，在这里预览文件。</div>')}</div>`};
function selectSopGroup(id){sopSelection=id;render()}
uploadSop=function(){if(!sopRequireEdit())return;sopUploadFiles=[];modal('上传 SOP / 创建文件组',`<div class="formgrid"><label class="field">指导书名称<input id="sopTitle" placeholder="例如：电芯绑定作业指导书"></label><label class="field">关联工序<select id="sopProcess">${steps.map((s,i)=>`<option value="${i}">${s}</option>`).join('')}</select></label><label class="field">版本号<input id="sopVersion" value="V1.0"></label><label class="field">图片 / PDF 每份停留时间（秒）<input id="sopSeconds" type="number" min="3" max="300" value="10"></label></div><label class="field" style="margin-top:18px">添加多份文件<input id="sopFiles" type="file" multiple accept="image/png,image/jpeg,image/webp,image/gif,application/pdf,video/mp4,video/webm" onchange="sopChooseFiles(this)"></label><p class="hint">每份最大 30 MB，每组最多 20 份、总计不超过 200 MB。可多次添加文件，再调整播放顺序。</p><div id="sopUploadList"></div>`,button('取消','closeModal()')+button('保存待审核',"submitSop()",'primary'))};
function sopChooseFiles(input){try{let incoming=[...input.files];incoming.forEach(sopType);if(incoming.some(f=>!f.size||f.size>30*1024*1024))throw Error('文件不能为空，且每份不能超过 30 MB');let all=[...sopUploadFiles,...incoming];if(all.length>20||all.reduce((a,f)=>a+f.size,0)>200*1024*1024)throw Error('每组最多 20 份文件，总大小不能超过 200 MB');sopUploadFiles=all;sopUploadList();input.value=''}catch(e){toast(e.message);input.value=''}}
function sopUploadList(){$('#sopUploadList').innerHTML=sopUploadFiles.map((f,i)=>`<div class="sop-file-row"><span class="badge">${i+1}</span><span class="fill">${escapeHtml(f.name)}<small>${(f.size/1024/1024).toFixed(2)} MB</small></span>${button('↑',`moveSopFile(${i},-1)`)}${button('↓',`moveSopFile(${i},1)`)}${button('移除',`removeSopFile(${i})`)}</div>`).join('')}
function moveSopFile(i,d){let j=i+d;if(j<0||j>=sopUploadFiles.length)return;[sopUploadFiles[i],sopUploadFiles[j]]=[sopUploadFiles[j],sopUploadFiles[i]];sopUploadList()}function removeSopFile(i){sopUploadFiles.splice(i,1);sopUploadList()}
submitSop=async function(){if(!sopRequireEdit()||sopUploading)return;let title=$('#sopTitle').value.trim(),version=$('#sopVersion').value.trim(),process=Number($('#sopProcess').value),seconds=Number($('#sopSeconds').value);if(!title||!version||!Number.isInteger(process)||process<0||process>=steps.length||!Number.isInteger(seconds)||seconds<3||seconds>300||!sopUploadFiles.length){toast('请填写名称、版本、工序、有效停留时间，并添加文件');return}let id='sop-'+crypto.randomUUID(),entries=sopUploadFiles.map((file,i)=>({id:id+'-'+i,file}));sopUploading=true;toast('正在保存 SOP 文件…');try{await sopStoreFiles(entries);let g={id,title,version,process,seconds,status:'待审核',created:new Date().toISOString(),files:entries.map(e=>({id:e.id,name:e.file.name,size:e.file.size,type:sopType(e.file)}))};sopGroups.unshift(g);try{saveSops()}catch(e){sopGroups.shift();await sopRemoveFiles(entries.map(x=>x.id));throw e}sopSelection=id;adminLog('上传 SOP 文件组',steps[process]+' / '+title+' / '+entries.length+' 份');closeModal();render();toast('文件已保存，可后台预览并审核发布')}catch(e){toast('保存失败：'+e.message)}finally{sopUploading=false}};
function publishSopGroup(id){if(!sopRequireEdit())return;let g=sopGroups.find(x=>x.id===id);if(!g)return;modal('审核并发布 SOP',detailRows([['名称',escapeHtml(g.title)],['关联工序',steps[g.process]],['版本',escapeHtml(g.version)],['文件数量',g.files.length+' 份'],['图片 / PDF 停留',g.seconds+' 秒']])+`<p class="hint">发布后同工序旧版归档，工位使用新版本。请先完成逐份预览。</p>`,button('取消','closeModal()')+button('确认发布',`activateSopGroup('${id}')`,'primary'))}
function activateSopGroup(id){if(!sopRequireEdit())return;let g=sopGroups.find(x=>x.id===id);if(!g)return;let previous=JSON.stringify(sopGroups);sopGroups.forEach(x=>{if(x.process===g.process&&x.status==='已发布')x.status='已归档'});g.status='已发布';try{saveSops();adminLog('发布 SOP',steps[g.process]+' / '+g.version);msgs.unshift({title:'SOP 已更新：'+steps[g.process],text:g.title+' '+g.version+'，共 '+g.files.length+' 份文件。',type:'需确认',time:'刚刚',read:false});closeModal();render();toast('SOP 已发布，关联工位自动使用该文件组')}catch(e){sopGroups=JSON.parse(previous);toast('发布失败：'+e.message)}}
function sopPlayerMarkup(g){return `<div class="sop-player" data-sop-group="${g.id}"><div class="sop-player-stage"><p class="sub">正在读取指导书…</p></div><div class="sop-player-info"></div><div class="sop-player-controls"></div></div>`}
function destroySopPlayers(){for(let p of sopPlayers.values()){if(!p.root.closest?.('#modal'))sopPlayback.set(p.g.id,{index:p.index,playing:p.playing,nextAt:p.nextAt||0,videoTime:p.root.querySelector('video')?.currentTime||0});p.active=false;clearTimeout(p.timer);if(p.url)URL.revokeObjectURL(p.url)}sopPlayers.clear()}
function mountSopPlayers(){document.querySelectorAll('[data-sop-group]').forEach(root=>{if(root.dataset.playerId&&sopPlayers.has(root.dataset.playerId))return;let g=sopGroups.find(x=>x.id===root.dataset.sopGroup);if(!g)return;let id='player-'+(++sopPlayerSeq);root.dataset.playerId=id;let cached=root.closest?.('#modal')?null:sopPlayback.get(g.id);let p={id,root,g,index:cached?.index||0,playing:cached?.playing??true,nextAt:cached?.nextAt||0,videoTime:cached?.videoTime||0,active:true,timer:null,url:null,load:0};if(p.nextAt&&p.playing&&p.nextAt<Date.now()&&g.files[p.index]?.type!=='video'){p.index=(p.index+1)%g.files.length;p.nextAt=0;}sopPlayers.set(id,p);showSopSlide(p)})}
async function showSopSlide(p){clearTimeout(p.timer);let request=++p.load;if(p.url){URL.revokeObjectURL(p.url);p.url=null}let f=p.g.files[p.index],stage=p.root.querySelector('.sop-player-stage');p.root.querySelector('.sop-player-info').textContent=(p.index+1)+' / '+p.g.files.length+'　'+f.name;p.root.querySelector('.sop-player-controls').innerHTML=button('上一份',`stepSopPlayer('${p.id}',-1)`)+button(p.playing?'暂停自动播放':'继续自动播放',`toggleSopPlayer('${p.id}')`)+button('下一份',`stepSopPlayer('${p.id}',1)`)+`<span class="sub">${p.g.seconds}秒 / 图片、PDF</span>`;stage.innerHTML='<p class="sub">正在读取文件…</p>';try{let blob=await sopReadFile(f.id);if(!p.active||request!==p.load)return;if(!blob)throw Error('当前浏览器缺少该文件，请在本机上传或接入后台文件服务');p.url=URL.createObjectURL(blob);if(f.type==='image')stage.innerHTML=`<img src="${p.url}" alt="${escapeHtml(f.name)}">`;else if(f.type==='pdf')stage.innerHTML=`<iframe src="${p.url}#toolbar=1" title="${escapeHtml(f.name)}"></iframe>`;else{stage.innerHTML=`<video src="${p.url}" controls muted playsinline ${p.playing?'autoplay':''}></video>`;let video=stage.querySelector('video');video.onloadedmetadata=()=>{if(p.videoTime&&Number.isFinite(video.duration))video.currentTime=Math.min(p.videoTime,Math.max(0,video.duration-.1))};video.onended=()=>{if(p.playing)stepSopPlayer(p.id,1)};video.onerror=()=>{stage.innerHTML='<p class="sub">视频无法播放，请核对文件编码或切换下一份。</p>'};return}if(p.playing&&p.g.files.length>1){if(!p.nextAt)p.nextAt=Date.now()+p.g.seconds*1000;p.timer=setTimeout(()=>stepSopPlayer(p.id,1),Math.max(1,p.nextAt-Date.now()))}}catch(e){if(p.active)stage.textContent=e.message}}
function stepSopPlayer(id,d){let p=sopPlayers.get(id);if(!p)return;p.index=(p.index+d+p.g.files.length)%p.g.files.length;p.nextAt=0;p.videoTime=0;showSopSlide(p)}function toggleSopPlayer(id){let p=sopPlayers.get(id);if(!p)return;p.videoTime=p.root.querySelector('video')?.currentTime||0;p.playing=!p.playing;p.nextAt=0;showSopSlide(p)}
function sopPreviewFile(id,index){let g=sopGroups.find(x=>x.id===id);if(!g)return;modal('SOP 文件预览',sopPlayerMarkup(g));mountSopPlayers();let root=$('#modal [data-sop-group]'),p=root&&sopPlayers.get(root.dataset.playerId);if(p){p.index=index;p.playing=false;showSopSlide(p)}}
wfSop=function(){let g=sopGroups.find(x=>x.process===wfStage&&x.status==='已发布');return g?panel('SOP · '+steps[wfStage],`<div class="actions" style="margin-bottom:12px">${badge(g.version)}${badge(g.files.length+' 份文件')}${badge('已发布')}</div>${sopPlayerMarkup(g)}`):panel('SOP · '+steps[wfStage],`<div class="sop-empty"><h3>当前工序暂无已发布 SOP</h3><p>在后台上传文件并关联“${steps[wfStage]}”，审核发布后在此自动播放。</p></div>`)};
const renderBeforeSopFiles=render;render=function(){destroySopPlayers();renderBeforeSopFiles();mountSopPlayers()};const closeBeforeSopFiles=closeModal;closeModal=function(){closeBeforeSopFiles();for(let [id,p] of sopPlayers){if(!p.root.isConnected){p.active=false;clearTimeout(p.timer);if(p.url)URL.revokeObjectURL(p.url);sopPlayers.delete(id)}}};
window.addEventListener('storage',e=>{if(e.key===SOPKEY&&e.newValue){try{let v=JSON.parse(e.newValue);if(Array.isArray(v)){sopGroups=v;render()}}catch{}}});
render();
